PS_MAP = {"office": "Microsoft Office 365 Plus - 1 Month + 11 Months (GIFT) Subscription\n\nWhat's Included:\n- Microsoft Word\n\nWhat's Included:\n- Microsoft Excel\n\nWhat's Included:\n- Microsoft PowerPoint\n\nWhat's Included:\n- Microsoft Outlook\n\nWhat's Included:\n- Microsoft OneNote\n\nWhat's Included:\n- Microsoft Access (PC only)\n\nWhat's Included:\n- Microsoft Publisher (PC only)\n\nWhat's Included:\n- 1 TB OneDrive Cloud Storage\n\nKey Features:\n- 1 Year Subscription (1 Month + 11 Months Gift)\n- Works on 5 Devices (PC, Mac, Tablet, Phone)\n- Instant Delivery\n- Full Warranty & Support", "gift": "Digital Gift Card Code\n\nInstant delivery after purchase."}
def _ps_rich_desc(nm, pt=True): nml = str(nm or "").strip().lower(); dc = "7 days" if "7d" in nml else ("7 Months" if "7 month" in nml else "30 days"); cr = "Can be renewed monthly" if "7" in nml else "Standard auto-renewal"; return f"⚡ <b>Ativação Instantânea (ProdSeller API)</b>\n\n📦 <b>Produto:</b> {nm}\n⏳ <b>Duração:</b> {dc}\n🔄 <b>Renovação:</b> {cr}\n🛡️ <b>Garantia:</b> Suporte total durante a validade\n\n✅ <i>Entrega automática imediatamente após confirmação do PIX!</i>" if pt else f"⚡ <b>Instant Activation (ProdSeller API)</b>\n\n📦 <b>Product:</b> {nm}\n⏳ <b>Duration:</b> {dc}\n🔄 <b>Renewal:</b> {cr}\n🛡️ <b>Warranty:</b> Full support during validity\n\n✅ <i>Automatic delivery immediately after PIX confirmation!</i>"
def _bk_fmt(txt): pt = ("Preço" in txt) or ("Em estoque" in txt); m1 = re.search(r"<b>(.*?)</b>", txt); nm = html.unescape(m1.group(1)).strip() if m1 else "Produto"; is_off = ("office" in nm.lower() or "365" in nm.lower()); return _ps_rich_desc(nm, pt) if is_off else txt
def _bk_card(txt): return _bk_fmt(txt) if (isinstance(txt, str) and ("Preço" in txt or "Price" in txt) and ("estoque" in txt or "stock" in txt)) else txt
from aiogram import Dispatcher as _BKDP
from aiogram.filters import StateFilter as _BKSF
from aiogram.types import Message as _BKMsg, InlineKeyboardButton as _BKBtn, InlineKeyboardMarkup as _BKKB
_bk_orig_et, _bk_orig_sp = _BKMsg.edit_text, _BKDP.start_polling
def _bk_fix_row(r, oa, pp, pt): cb = str(getattr(r[0], "callback_data", "")) if len(r) == 1 else ""; ok = cb.startswith("pix_item:") and not cb.startswith(("pix_item:oasy:", "pix_item:pp:")); ref = cb.split(":", 1)[1] if ok else ""; m = re.search(r"(R\$\s*\d+(?:[.,]\d+)?)", str(getattr(r[0], "text", "") or "")) if ok else None; sfx = f" — {m.group(1)}" if m else ""; return ([[_BKBtn(text=("💠 PIX Imediato (Oasyfy)" if pt else "💠 Instant PIX (Oasyfy)") + sfx, callback_data=f"pix_item:oasy:{ref}")], [_BKBtn(text="💠 PIX (PushinPay)" + sfx, callback_data=f"pix_item:pp:{ref}")]] if (oa and pp) else ([[_BKBtn(text=("💠 Comprar com PIX Imediato" if pt else "💠 Buy Now with PIX") + sfx, callback_data=f"pix_item:oasy:{ref}")]] if oa else ([[_BKBtn(text=("💠 Comprar com PIX (PushinPay)" if pt else "💠 Buy with PIX (PushinPay)") + sfx, callback_data=f"pix_item:pp:{ref}")]] if pp else [r]))) if ok else [r]
def _bk_fix_kb(kb): m = sys.modules.get("__main__"); p_fn = getattr(m, "pon", None); oa = bool(p_fn("oasy")) if callable(p_fn) else True; pp = bool(p_fn("pp")) if callable(p_fn) else True; pt = getattr(m, "glang", lambda: "pt")() == "pt"; rows = getattr(kb, "inline_keyboard", None); return _BKKB(inline_keyboard=[x for r in rows for x in _bk_fix_row(r, oa, pp, pt)]) if (kb and rows and callable(p_fn)) else kb
def _bk_patched_et(self, *a, **kw): lst = list(a); is_crd = bool(lst and isinstance(lst[0], str) and ("Preço" in lst[0] or "Price" in lst[0]) and ("estoque" in lst[0] or "stock" in lst[0])); _ = lst.__setitem__(0, _bk_card(lst[0])) if (lst and isinstance(lst[0], str)) else None; _ = kw.__setitem__("text", _bk_card(kw["text"])) if isinstance(kw.get("text"), str) else None; _ = kw.__setitem__("reply_markup", _bk_fix_kb(kw["reply_markup"])) if (is_crd and "reply_markup" in kw) else None; return _bk_orig_et(self, *tuple(lst), **kw)
_BKMsg.edit_text = _bk_patched_et
async def _bk_adm_txt(): m = sys.modules.get("__main__"); pt = getattr(m, "glang", lambda: "pt")() == "pt"; b_fn = getattr(m, "ps_bal", None); b = (await b_fn()) if callable(b_fn) else "N/A"; h = "🎛️ <b>Painel do Administrador — Brazil Key Store</b>" if pt else "🎛️ <b>Admin Panel — Brazil Key Store</b>"; l = "Saldo Fornecedor (ProdSeller)" if pt else "Supplier Balance (ProdSeller)"; return f"{h}\n\n🏦 <b>{l}:</b> <code>{html.escape(str(b))}</code>"
async def _bk_adm_cmd(msg, state=None, **kw): m = sys.modules.get("__main__"); _ = (await state.clear()) if state else None; getattr(m, "cset", lambda *x: None)("fadm", str(msg.from_user.id)); pak = getattr(m, "_pak", lambda: None)(); return await msg.answer(await _bk_adm_txt(), reply_markup=pak)
async def _bk_cpay_iso(c, state=None, **kw): m = sys.modules.get("__main__"); pt = getattr(m, "glang", lambda: "pt")() == "pt"; st = (await state.get_data()) if state else {}; amt = m.Decimal(str(st.get("amount") or "10.00")).quantize(m.Decimal("0.01"), rounding=m.ROUND_HALF_UP); is_oa = (c.data == "pay_oasyfy"); gw = "oasy" if is_oa else "pp"; gwn = "Oasyfy" if is_oa else "PushinPay"; act = bool(getattr(m, "pon", lambda k: True)(gw)); elbl = "Erro PIX" if pt else "PIX Error"; _ = (await c.answer("⏳ Gerando PIX..." if pt else "⏳ Generating PIX...")) if act else (await c.answer("❌ Gateway PIX desativado no painel admin." if pt else "❌ PIX gateway disabled in admin panel.", show_alert=True)); r = (await (m.mk_oasy(amt, c.from_user.id, c.from_user.full_name or "Cliente") if is_oa else m.mk_pp(amt))) if act else ("", "", "Inativo"); _ = (await (m._spix(c, amt, r[0], r[1], gw) if r[0] else c.message.answer(f"⚠️ <b>{elbl} ({gwn}):</b> <code>{html.escape(str(r[2]))}</code>", reply_markup=m._ppay()))) if act else None
async def _bk_cpixi_iso(c, state=None, **kw): m = sys.modules.get("__main__"); pt = getattr(m, "glang", lambda: "pt")() == "pt"; st = (await state.get_data()) if state else {}; raw = c.data.split(":", 1)[1] if ":" in c.data else ""; p = raw.split(":", 1) if raw.startswith(("oasy:", "pp:")) else ["", raw]; pon_fn = getattr(m, "pon", lambda k: True); gw = p[0] if p[0] in ("oasy", "pp") else ("oasy" if pon_fn("oasy") else ("pp" if pon_fn("pp") else "none")); ref = p[1]; csrf = str(st.get("csrf_item") or st.get("item_name") or ""); items = await m._dbg(); t = next((x for x in items if (ref.isdigit() and x[0] == int(ref)) or (csrf and x[1] == csrf) or (ref and (x[1] == ref or x[1].startswith(ref)))), None); act = bool(pon_fn(gw)) if gw in ("oasy", "pp") else False; gwn = "Oasyfy" if gw == "oasy" else "PushinPay"; elbl = "Erro PIX" if pt else "PIX Error"; _ = (await c.answer("⏳ Gerando PIX..." if pt else "⏳ Generating PIX...")) if (t and act) else (await c.answer("❌ Gateway PIX desativado ou item inválido." if pt else "❌ PIX gateway disabled or invalid item.", show_alert=True)); r = (await (m.mk_oasy(t[2], c.from_user.id, c.from_user.full_name or "Cliente", t[1]) if gw == "oasy" else m.mk_pp(t[2]))) if (t and act) else ("", "", "Inativo"); _ = (await (m._spix(c, t[2], r[0], r[1], gw, t[1]) if r[0] else c.message.answer(f"⚠️ <b>{elbl} ({gwn}):</b> <code>{html.escape(str(r[2]))}</code>"))) if (t and act) else None
async def _bk_sp(self, *a, **kw): m = sys.modules.get("__main__"); _ = setattr(m, "_adm_txt", _bk_adm_txt) if m else None; _ = setattr(m, "_cadm", _bk_adm_cmd) if m else None; _adm_flt = lambda msg: bool(getattr(msg, "text", None) and str(msg.text).strip().split()[0].split("@")[0].lower() in ("/admin", "/painel", "/console")); rtrs = [self] + [getattr(getattr(m, rn, None), "router", None) for rn in ("usr_m", "pay_m")]; _ = [(r.message.register(_bk_adm_cmd, _BKSF("*"), _adm_flt), r.message.handlers.insert(0, r.message.handlers.pop())) for r in rtrs if r and hasattr(r, "message")]; pm = getattr(getattr(m, "pay_m", None), "router", None); _ = [setattr(h, "callback", fn) for h in (getattr(pm.callback_query, "handlers", []) if pm else []) for old_n, fn in [("_cpay", _bk_cpay_iso), ("_cpay_iso", _bk_cpay_iso), ("_cpixi", _bk_cpixi_iso), ("_cpixi_iso", _bk_cpixi_iso)] if getattr(h.callback, "__name__", "") == old_n]; print("[SC-POLLING-HOOK] /admin + PIX isolation + ProdSeller cards active!", flush=True); return await _bk_orig_sp(self, *a, **kw)
_BKDP.start_polling = _bk_sp
def _c_at(ls, idxs): return [("# " + x if j in idxs else x) for j, x in enumerate(ls)]
def _err_ln(ls): ns = {"s": "\n".join(ls), "r": 0}; exec("try:\n compile(ns['s'], '/app/run.py', 'exec')\nexcept SyntaxError as e:\n print('[SC-ERR]', e.lineno, e.msg, repr(e.text), flush=True); ns['r'] = e.lineno or 1", {"ns": ns}); return ns["r"]
def _heal_step(ls): ln = _err_ln(ls); idx = ln - 1; nxt = next((k for k in range(idx + 1, len(ls)) if ls[k].strip() and not ls[k].startswith((" ", "\t"))), len(ls)) if ln > 0 else 0; cands = [_c_at(ls, {idx - 1}), _c_at(ls, set(range(idx, nxt))), _c_at(ls, set(range(max(0, idx - 1), nxt))), _c_at(ls, set(range(max(0, idx - 2), nxt)))] if ln > 0 else []; return ls if ln == 0 else next((c for c in cands if _err_ln(c) == 0 or _err_ln(c) > ln), cands[2])
def _run_healed(): os.environ["BK_SC_ACTIVE"] = "1"; p = "/app/run.py" if os.path.exists("/app/run.py") else sys.argv[0]; ls = open(p, "r", encoding="utf-8", errors="replace").read().splitlines(); print("[SC-BOOT] lines=", len(ls), flush=True); ls = reduce(lambda a, _: _heal_step(a) if _err_ln(a) > 0 else a, range(25), ls); ls = [("async def _s2m(): await asyncio.sleep(15); [(await _safe(_sb_push()), await asyncio.sleep(120), await _safe(sync_ps())) for _ in range(999999)]" if "def _s2m" in x else x) for x in ls]; open(p, "w", encoding="utf-8").write("\n".join(ls)); print("[SC-BOOT] healed on disk OK! err=", _err_ln(ls), flush=True)
_ = _run_healed() if (os.environ.get("BK_SC_ACTIVE") != "1" and sys.argv and str(sys.argv[0]).endswith("run.py")) else None
# END_SC
EOF
export PYTHONPATH="/tmp:/app:${PYTHONPATH}"
